import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    // 2026-10-31 12:00 UTC; 30 Warsaw days earlier is 2026-10-01 12:00 CEST (10:00 UTC)
    private static final Instant NOW = Instant.parse("2026-10-31T12:00:00Z");

    private final OrderRepository repository = new OrderRepository();
    private final OrderService service =
            new OrderService(repository, Clock.fixed(NOW, ZoneOffset.UTC));

    private String order(String placedAt) {
        return service.place("c-1", Money.pln(1000), Instant.parse(placedAt));
    }

    @Test
    void cancelsPlacedOrdersOlderThanThirtyDays() {
        String old = order("2026-09-01T10:00:00Z");
        String recent = order("2026-10-15T10:00:00Z");

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", service.summary(old).status());
        assertEquals("PLACED", service.summary(recent).status());
    }

    @Test
    void leavesOrdersExactlyThirtyDaysOldAlone() {
        // cutoff is 2026-10-01T10:00:00Z (30 days before 2026-10-31 in Warsaw, CEST +2h)
        String boundary = order("2026-10-01T10:00:00Z");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(boundary).status());
    }

    @Test
    void doesNotTouchOrdersInOtherStatuses() {
        String confirmed = order("2026-08-01T10:00:00Z");
        service.confirm(confirmed);
        String cancelled = order("2026-08-01T10:00:00Z");
        service.cancel(cancelled);

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", service.summary(confirmed).status());
        assertEquals("CANCELLED", service.summary(cancelled).status());
    }

    @Test
    void isIdempotent() {
        order("2026-08-01T10:00:00Z");

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }
}
}

